SELECT
LEFT(update_time, 10) dataTime,
LEFT(update_time, 7) dataTime,
COUNT(*) totalCount, SUM(total_cost) totalCost, SUM(total_qt) totalQt FROM `b_order_record` WHERE site_id = #{siteId}
AND run_mode IN (1, 2)
AND run_mode = #{runMode}
AND update_time BETWEEN #{startTime} AND #{endTime}
GROUP BY LEFT(update_time, 10)
GROUP BY LEFT(update_time, 7)

SELECT
LEFT(o.update_time, 10) dataTime,
LEFT(o.update_time, 7) dataTime,
COUNT(*) totalCount, SUM(s.actual_total_cost) totalCost, SUM(o.total_qt) totalQt FROM b_order_record o LEFT JOIN b_settlement_record s ON o.order_num = s.order_num WHERE o.site_id = #{siteId}
AND o.run_mode IN (1, 2)
AND o.run_mode = #{runMode}
AND o.update_time BETWEEN #{startTime} AND #{endTime}
GROUP BY LEFT(o.update_time, 10)
GROUP BY LEFT(o.update_time, 7)
